package com.pandinila.broadband_management.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> missing(Exception e){return error(HttpStatus.NOT_FOUND,e.getMessage());}@ExceptionHandler(IllegalStateException.class) ResponseEntity<?> conflict(Exception e){return error(HttpStatus.CONFLICT,e.getMessage());}@ExceptionHandler(Exception.class) ResponseEntity<?> bad(Exception e){return error(HttpStatus.BAD_REQUEST,e.getMessage());}private ResponseEntity<?> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("timestamp", Instant.now(),"status",s.value(),"error",s.getReasonPhrase(),"message",m==null?"Request failed":m));}}
